  ok=x.notna()&peer.notna(); xx=x[ok];pp=peer[ok]
  # affine peer residual and slope1 demeaned residual
  a,b=np.polyfit(pp,xx,1);ra=xx-(a*pp+b);rs=(xx-xx.mean())-(pp-pp.mean())
  row={'st':st,'pol':p,'dist':di,'n':len(xx)}
