     q=W[v][di].loc[res.index]
     aa=res.copy();bb=q.copy()
     if env_scope=='detrend':
      t=np.arange(len(aa));aa=aa-np.polyval(np.polyfit(t,aa,1),t);bb=bb-np.polyval(np.polyfit(t,bb,1),t)
     elif env_scope=='diff':aa=aa.diff();bb=bb.diff()
     elif env_scope=='day':
      dd=aa.index.date;aa=aa-aa.groupby(dd).transform('mean');bb=bb-bb.groupby(dd).transform('mean')
     c=aa.corr(bb)
     if abs(c)>abs(best[1]):best=(v,c)
    row[rn+'_'+env_scope+'_v'],row[rn+'_'+env_scope+'_c']=best
  rows.append(row)
 d=pd.DataFrame(rows).set_index('st')
 print('\n### BASE',base)
 for metric in ['aff_raw_c','aff_detrend_c','aff_diff_c','aff_day_c','sub_raw_c']:
  z=d[['pol','dist','n',metric.replace('_c','_v'),metric]].copy();z['abs']=z[metric].abs();print('\n',metric);print(z.sort_values('abs',ascending=False).head(15).round(3).to_string())
 print('\ncandidates');print(d.loc[['ST019','ST012','ST060','ST066','ST040','ST051']].round(3).to_string())
